Site.UrlRewriter rewriter = new Site.UrlRewriter();
List<PageReference> input = new List<PageReference>{new PageReference('/apex/source?id=001000000000001')};
List<PageReference> generated = rewriter.generateUrlFor(input);
System.assertEquals(1, generated.size());
System.assertEquals('/apex/source?id=001000000000001', generated[0].getUrl());
generated[0].getParameters().put('changed', 'true');
System.assertEquals(null, input[0].getParameters().get('changed'));
PageReference mapped = rewriter.mapRequestUrl(new PageReference('/apex/request?mode=view'));
System.assertEquals('/apex/request?mode=view', mapped.getUrl());

